import spidev
import time

class LoadCellReader:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 50000
        self.spi.mode = 0b00
        self.spi.bits_per_word = 8

    def read_raw_data(self):
        try:
            response = self.send_spi_command(self.spi, [0x01, 0x80, 0x00])
            raw_data = self.extract_10bit(response)
            return raw_data
        except OSError as e:
            print(f"Error reading raw data: {e}")
            return None

    def convert_to_weight(self, raw_data):
        weight = float(raw_data) * (5.0 / 1023.0)
        return weight

    def send_spi_command(self, spi, data):
        try:
            response = spi.xfer2(data)
            return response
        except OSError as e:
            print(f"Error sending SPI command: {e}")
            return None

    def extract_10bit(self, response):
        raw_data = ((response[1] & 0x03) << 8) | response[2]
        return raw_data

    def close(self):
        self.spi.close()

def main():
    load_cell_reader = LoadCellReader()
    while True:
        try:
            raw_data = load_cell_reader.read_raw_data()
            if raw_data is not None:
                weight = load_cell_reader.convert_to_weight(raw_data)
                print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
        except KeyboardInterrupt:
            print("Shutting down...")
            load_cell_reader.close()
            break
        except Exception as e:
            print(f"Error: {e}")
            load_cell_reader.close()
            break

if __name__ == "__main__":
    main()

