import logging
import queue
import threading
import time

import RPi.GPIO as GPIO
import spidev


class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue

        if self.sensor_type == "digital":
            self.setup_digital_sensor()
        elif self.sensor_type == "analog":
            self.setup_analog_sensor()
        else:
            raise ValueError("Invalid sensor type: {}".format(self.sensor_type))

    def setup_digital_sensor(self):
        GPIO.setmode(GPIO.BCM)
        for pin in self.gpio_pins:
            GPIO.setup(pin, GPIO.IN)

    def setup_analog_sensor(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = self.spi_speed

    def read_digital_sensor(self):
        for pin in self.gpio_pins:
            if GPIO.input(pin) == 1:
                return True
        return False

    def read_analog_sensor(self):
        for channel in self.channels:
            self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = self.spi.xfer2([0])
            value = (data[1] & 0x3) << 8 | data[2]
            if value >= self.threshold:
                return True
        return False

    def run(self):
        while True:
            if self.sensor_type == "digital":
                if self.read_digital_sensor():
                    self.log_queue.put("Sound detected on sensor {}".format(self.sensor_id))
                    time.sleep(0.1)
            elif self.sensor_type == "analog":
                if self.read_analog_sensor():
                    self.log_queue.put("Sound detected on sensor {}".format(self.sensor_id))
                    time.sleep(0.1)
            time.sleep(1 / self.sample_rate)

    def stop(self):
        if self.sensor_type == "digital":
            GPIO.cleanup()
        elif self.sensor_type == "analog":
            self.spi.close()


def main():
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"])
    parser.add_argument("--threshold", type=int, default=100)
    parser.add_argument("--sample_rate", type=int, default=10)
    parser.add_argument("--log_file", required=True)
    parser.add_argument("--gpio_pins", nargs="+", type=int, default=[])
    parser.add_argument("--channels", nargs="+", type=int, default=[])
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", nargs="+", type=int, default=[])
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO)

    sensors = []
    for sensor_id in args.sensor_ids:
        sensors.append(SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed))

    log_queue = queue.Queue()
    for sensor in sensors:
        threading.Thread(target=sensor.run, args=(log_queue,)).start()

    try:
        while True:
            try:
                message = log_queue.get(block=False)
                logging.info(message)
            except queue.Empty:
                pass
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()


if __name__ == "__main__":
    main()

