import spidev
import time

class MQ2Sensor:
    def __init__(self, spi_bus, cs_pin, adc_channel):
        self.spi = spidev.SpiDev(spi_bus, cs_pin)
        self.adc_channel = adc_channel

    def read_adc(self):
        try:
            raw_value = self.spi.xfer2([1, (8 + self.adc_channel) << 4, 0])
            return (raw_value[1] & 0x3FF) << 2
        except OSError as e:
            print(f"Error reading ADC: {e}")
            return None

    def get_gas_concentration(self, raw_value):
        voltage = (raw_value / 1023) * 3.3
        ppm = voltage * 200
        return ppm

    def get_alert_level(self, ppm):
        if ppm < 150:
            return "safe"
        elif ppm < 399:
            return "warning"
        else:
            return "danger"

def main():
    sensor = MQ2Sensor(0, 0, 0)
    for i in range(12):
        raw_value = sensor.read_adc()
        if raw_value is None:
            continue
        ppm = sensor.get_gas_concentration(raw_value)
        alert_level = sensor.get_alert_level(ppm)
        print(f"Reading {i+1}: {ppm} ppm ({alert_level})")
        time.sleep(0.5)

if __name__ == "__main__":
    main()

