logging.basicConfig(filename='distance_log.txt', level=logging.INFO)

def read_distance():
    try:
        with serial.Serial('/dev/serial0', 9600, timeout=1) as ser:
            while True:
                line = ser.readline().decode('utf-8').strip()
                try:
                    distance = float(line)
                    logging.info(f'{time.time()}, {distance}')
                    print(f'{time.time()}, {distance}')
