import gpiozero
import picamera2
import adafruit_circuitpython_gps
import paho.mqtt.client as mqtt

def degrees_decimal_to_dms(degrees_decimal: float) -> Tuple[int, int, float]:
    if not isinstance(degrees_decimal, float):
        raise TypeError("degrees_decimal must be a float")
    if degrees_decimal < 0:
        sign = -1
    else:
        sign = 1
    degrees = int(abs(degrees_decimal))
    minutes = int((abs(degrees_decimal) - degrees) * 60)
    seconds = (abs(degrees_decimal) - degrees - minutes / 60) * 3600
    return (sign * degrees, minutes, seconds)

def number_to_exif_rational(number: Real) -> Tuple[int, int]:
    if not isinstance(number, Real):
        raise TypeError("number must be a real number")
    numerator = int(number)
    denominator = 1
    while abs(numerator / denominator - number) > 0.001:
        denominator += 1
        if denominator > 1000:
            raise ValueError("number cannot be converted to a fraction with a denominator less than 1000")
    return (numerator, denominator)

def gps_to_exif(gps_data: adafruit_circuitpython_gps.GPSData) -> Tuple[int, int, float, int, int, float]:
    latitude = degrees_decimal_to_dms(gps_data.latitude)
    longitude = degrees_decimal_to_dms(gps_data.longitude)
    altitude = number_to_exif_rational(gps_data.altitude)
    return (latitude[0], latitude[1], latitude[2], longitude[0], longitude[1], longitude[2], altitude[0], altitude[1])

def main():
    gps = adafruit_circuitpython_gps.GPS(uart=gpiozero.UART(tx=23, rx=24))
    camera = picamera2.PiCamera2()
    client = mqtt.Client()
    client.connect("localhost")
    client.loop_start()
    while True:
        gps_data = gps.get_data()
        if gps_data.has_fix:
            exif_data = gps_to_exif(gps_data)
            camera.capture(exif_data=exif_data)
            client.publish("gps/location", json.dumps(exif_data))
        time.sleep(1)

if __name__ == "__main__":
    main()

