from picamera2 import PiCamera2
from picamera2.transforms import VerticalFlip

from config import Config
from mail_config import MailConfig

app = Flask(__name__)
app.config.from_object(Config)
mail = Mail(app)

camera = PiCamera2(resolution=(640, 480), transform=VerticalFlip())

class Camera:
    def __init__(self):
        self.camera = PiCamera2(resolution=(640, 480), transform=VerticalFlip())
        self.camera.start_preview()

    def get_frame(self):
        return self.camera.get_frame()

    def get_object(self, classifier):
        return self.camera.get_object(classifier)

    def get_object_with_basic_motion_detection(self):
        return self.camera.get_object_with_basic_motion_detection()

    def stop(self):
        self.camera.stop_preview()
        self.camera.close()

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/video_feed')
def video_feed():
    return Response(gen(Camera()), mimetype='multipart/x-mixed-replace; boundary=frame')

def gen(camera):
    while True:
        frame = camera.get_frame()
        yield (b'--frame\r\n'
               b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n')

def check_for_objects(camera, config):
    if config.classifier_name == 'motion_detector':
        object_detected = camera.get_object_with_basic_motion_detection()
    else:
        object_detected = camera.get_object(config.classifier)

    if object_detected and config.send_email_notifications:
        if time.time() - config.last_email_time > config.email_send_interval:
            try:
                mail_config.send_email(frame, config)
                config.last_email_time = time.time()
            except Exception as e:
                logging.error(f'Error sending email: {e}')

def signal_handler(signal, frame):
    camera.stop()
    sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        camera.start()
        while True:
            check_for_objects(camera, config)
            time.sleep(1)
    except Exception as e:
        logging.error(f'Error initializing camera: {e}')
        sys.exit(1)

