import picamera2
import speech_recognition as sr
import time

# Set up GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(17, GPIO.OUT)
GPIO.setup(4, GPIO.IN)

# Set up DHT11 sensor
dht = adafruit_dht.DHT11(GPIO.input(4))

# Set up camera
camera = picamera2.PiCamera2()
camera.resolution = (640, 480)

# Set up speech recognition
r = sr.Recognizer()
m = sr.Microphone()

def turn_lights_on():
    GPIO.output(17, GPIO.HIGH)

def turn_lights_off():
    GPIO.output(17, GPIO.LOW)

def read_temperature():
    try:
        temperature = dht.read_temperature()
        return temperature
    except adafruit_dht.DHTError:
        return None
    except OSError:
        return None

def take_picture():
    try:
        camera.capture('greenhouse_{}.jpg'.format(time.time()))
    except picamera2.PiCamera2Error:
        return None

def listen_for_voice_commands():
    try:
        with m as source:
            r.adjust_for_ambient_noise(source, duration=1)
            audio = r.listen(source, timeout=5)
            command = r.recognize_google(audio)
            if command == 'Greenhouse turn on the lights':
                turn_lights_on()
            elif command == 'Greenhouse turn off the lights':
                turn_lights_off()
            elif command == 'Greenhouse what is the temperature':
                temperature = read_temperature()
                if temperature is not None:
                    print('The temperature is {} degrees Celsius'.format(temperature))
                else:
                    print('I couldn\'t read the temperature')
            elif command == 'Greenhouse take a picture':
                take_picture()
            else:
                print('I didn\'t understand that command')
    except sr.UnknownValueError:
        print('I didn\'t understand that command')
    except sr.RequestError:
        print('I couldn\'t understand the command')

# Set up signal handlers for SIGINT and SIGTERM
def signal_handler(signal, frame):
    turn_lights_off()
    camera.close()
    GPIO.cleanup()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Main loop
while True:
    listen_for_voice_commands()
    time.sleep(1)

