import io
import picamera2
import cv2
import numpy as np

class CameraStreamBuffer:
    def __init__(self, c):
        self.c = c
        self.b = io.BytesIO()
        self.frame_type = None

    def write(self, d):
        try:
            self.b.write(d)
            if self.c.current_configuration()['encode'] == 'h264':
                frame_type = self.c.current_configuration()['frame_type']
                if frame_type != 1:
                    self.flush()
                    self.reset()
        except IOError as e:
            print(f"I/O error: {e}")

    def flush(self):
        self.b.seek(0)
        self.c.write(self.b.read())
        self.b.truncate(0)

    def reset(self):
        self.b.seek(0)
        self.b.truncate(0)

class MotionDetectionBuffer:
    def __init__(self, f):
        self.f = f
        self.b = io.BytesIO()
        self.previous_frame = None

    def write(self, d):
        try:
            self.b.write(d)
            if self.b.read(2) == b'\xff\xd8':
                frame = cv2.imdecode(np.frombuffer(self.b.read(), dtype=np.uint8), cv2.IMREAD_COLOR)
                if self.previous_frame is not None:
                    self.f(self.previous_frame, frame)
                self.previous_frame = frame
                self.b.truncate(0)
        except IOError as e:
            print(f"I/O error: {e}")
        except cv2.error as e:
            print(f"CV2 error: {e}")

