import json
import random
import threading
import time

import paho.mqtt.client as mqtt

def generate_temperature_payload(index):
    temperature = round(random.uniform(19.0, 26.0), 2)
    payload = {
        "index": index,
        "temperature": temperature
    }
    return json.dumps(payload)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected to MQTT broker")
    else:
        print(f"Connection failed with result code {rc}")

def on_publish(client, userdata, mid):
    print(f"Message {mid} published")

def publish_temperature(client):
    for i in range(5):
        payload = generate_temperature_payload(i)
        client.publish("classroom/temperature", payload)
        time.sleep(1)

def main():
    client = mqtt.Client(protocol=mqtt.MQTTv311)
    client.on_connect = on_connect
    client.on_publish = on_publish

    connected = threading.Event()
    client.connect("test.mosquitto.org", 1883, 60, connected)
    connected.wait()

    publish_temperature(client)

    client.disconnect()

    return 0

if __name__ == "__main__":
    exit(main())

import logging
import smbus2
import time

class DHT20:
    def __init__(self, address=0x38, bus=1):
        self.address = address
        self.bus = bus
        self.logger = logging.getLogger(__name__)

        try:
            self.bus = smbus2.SMBus(bus)
            self.logger.info("I2C bus opened successfully")
        except OSError as e:
            self.logger.error("Failed to open I2C bus: {}".format(e))
            raise

        time.sleep(0.5)

        try:
            status = self.bus.read_byte_data(self.address, 0x71)
            if (status & 0x18) != 0x18:
                self.logger.error("Sensor not ready: status={}".format(status))
                raise ValueError("Sensor not ready")
        except OSError as e:
            self.logger.error("Failed to read sensor status: {}".format(e))
            raise

    def get_temperature_and_humidity(self):
        for i in range(5):
            try:
                self.bus.write_byte_data(self.address, 0xAC, 0x33)
                self.bus.write_byte_data(self.address, 0xAC, 0x00)

                status = self.bus.read_byte_data(self.address, 0x71)
                while (status & 0x80) == 0x80:
                    time.sleep(0.1)
                    status = self.bus.read_byte_data(self.address, 0x71)

                data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
                raw_humidity = (data[1] << 16) | (data[2] << 8) | data[3]
                raw_temperature = (data[4] << 16) | (data[5] << 8) | data[6]
                crc = data[7]

