import gpiozero

class LEDController:
    def __init__(self, pin):
        try:
            self.led = gpiozero.DigitalOutputDevice(pin)
        except ValueError as e:
            print(f"Error initializing LED: {e}")
            raise

    def on(self):
        self.led.on()

    def off(self):
        self.led.off()

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Durations must be non-negative")
        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

def main():
    try:
        led = LEDController(25)
        while True:
            led.blink(1.0, 0.5)
    except KeyboardInterrupt:
        print("Received keyboard interrupt, turning off LED")
        led.off()
    except Exception as e:
        print(f"Error: {e}")
    finally:
        print("Releasing resources and exiting")
        led.off()
        gpiozero.cleanup()

if __name__ == "__main__":
    main()

