sensor.integration_time = adafruit_tcs34725.INTEGRATION_TIME_50MS
sensor.gain = adafruit_tcs34725.GAIN_4X

def get_sensor_color_data():
    try:
        color_rgb_bytes = sensor.color_rgb_bytes
        return (color_rgb_bytes[0], color_rgb_bytes[1], color_rgb_bytes[2], color_rgb_bytes[3])
    except:
        print("Error reading sensor data")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    try:
        image = Image.open(image_path)
        image.thumbnail((100, 100))
        color_count = image.getcolors()
        dominant_color = color_count[0][1]
        return dominant_color
    except FileNotFoundError:
        print("Image file not found")
        return (0, 0, 0)
    except:
        print("Error reading image data")
        return (0, 0, 0)

def main():
    while True:
        sensor_color = get_sensor_color_data()
        image_color = find_dominant_image_color("image.jpg")
        print(f"Sensor color: {sensor_color}")
        print(f"Image color: {image_color}")
        time.sleep(1)

if __name__ == "__main__":
    main()

# Clean shutdown on KeyboardInterrupt and SIGTERM
def signal_handler(signal, frame):
    print("Shutting down")
    i2c.deinit()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

