import pigpio

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, pigpio, pin):
        self.pi = pigpio
        self.pin = pin
        self.frequency = 1000
        self.duty_cycle = 0

        self.pi.set_mode(self.pin, pigpio.OUTPUT)
        self.pi.set_PWM_frequency(self.pin, self.frequency)
        self.pi.set_PWM_dutycycle(self.pin, self.duty_cycle)

    def set_frequency(self, freq):
        if not isinstance(freq, int):
            raise MotorError("Frequency must be an integer")
        if freq < 0:
            raise MotorError("Frequency must be positive")
        self.frequency = freq
        self.pi.set_PWM_frequency(self.pin, self.frequency)

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int):
            raise MotorError("Duty cycle must be an integer")
        if duty < 0 or duty > 255:
            raise MotorError("Duty cycle must be between 0 and 255")
        self.duty_cycle = duty
        self.pi.set_PWM_dutycycle(self.pin, self.duty_cycle)

    def stop(self):
        self.duty_cycle = 0
        self.pi.set_PWM_dutycycle(self.pin, self.duty_cycle)

    def __del__(self):
        self.stop()
        self.pi.stop()

    def close(self):
        self.stop()
        self.pi.stop()

