        self.ser = serial.Serial(port, baudrate, timeout=timeout)
        self.modbus = pymodbus.ModbusSerialClient(method='rtu', port=self.ser)
        self.modbus.connect()

        self.register_map = {
            'CONTROL': {
                'R/W': 'W',
                'Register': 0x3100,
                'functioncode': 0x06,
                'Value': {
                    'Stop': 0x0006,
                    'Start': 0x000F
                }
            },
            'STATUS': {
                'R/W': 'R',
                'Register': 0x3000,
                'functioncode': 0x03
            },
            'OPMODE': {
                'R/W': 'W',
                'Register': 0x3500,
                'functioncode': 0x06,
                'Value': {
                    'Position': 1
                }
            },
            'VelocityFeedback': {
                'R/W': 'R',
                'Register': 0x3B00,
                'functioncode': 0x03,
                'read_length': 2
            },
            'PositionFeedback': {
                'R/W': 'R',
                'Register': 0x3700,
                'functioncode': 0x03,
                'read_length': 2
            },
            'PositionCommand': {
                'R/W': 'W',
                'Register': 0x4000,
                'functioncode': 0x06
            },
            'VelocityCommand': {
                'R/W': 'W',
                'Register': 0x6F00,
                'functioncode': 0x06
            }
        }

    def read_register(self, register):
        try:
            result = self.modbus.read_holding_registers(register['Register'], register['read_length'], unit=1)
            return result.registers
        except pymodbus.ModbusError as e:
            logging.error(f'Modbus error: {e}')
            return None

    def write_register(self, register, value):
        try:
            self.modbus.write_single_register(register['Register'], value, unit=1)
        except pymodbus.ModbusError as e:
            logging.error(f'Modbus error: {e}')

    def start(self):
        self.write_register(self.register_map['CONTROL'], self.register_map['CONTROL']['Value']['Start'])

    def stop(self):
        self.write_register(self.register_map['CONTROL'], self.register_map['CONTROL']['Value']['Stop'])

    def get_status(self):
        return self.read_register(self.register_map['STATUS'])

    def get_opmode(self):
        return self.read_register(self.register_map['OPMODE'])

    def get_velocity_feedback(self):
        return self.read_register(self.register_map['VelocityFeedback'])

    def get_position_feedback(self):
        return self.read_register(self.register_map['PositionFeedback'])

    def set_position_command(self, value):
        self.write_register(self.register_map['PositionCommand'], value)

    def set_velocity_command(self, value):
        self.write_register(self.register_map['VelocityCommand'], value)

    def close(self):
        self.modbus.close()
        self.ser.close()

if __name__ == '__main__':
    servo = Servo()
    servo.start()
    print(servo.get_status())
    print(servo.get_opmode())
    print(servo.get_velocity_feedback())
    print(servo.get_position_feedback())
    servo.set_position_command(1000)
    servo.set_velocity_command(100)
    print(servo.get_position_feedback())
    servo.stop()
    servo.close()

