import logging
import time
import automationhat

class GarageDoor:
    def __init__(self, state_pin):
        self.state_pin = state_pin
        self.state = None
        self.relay = automationhat.relay.one
        self.relay.off()

        if not automationhat.is_connected():
            logging.error("Automation HAT not connected")
            exit(1)

        self.state = self.read_state()

    def read_state(self):
        try:
            state = automationhat.input.one.read()
            if state is None:
                logging.error("Invalid state read from Automation HAT")
                exit(1)
            return state
        except automationhat.AutomationHatError as e:
            logging.error("Error reading state from Automation HAT: %s", e)
            exit(1)

    def trigger(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
        except automationhat.AutomationHatError as e:
            logging.error("Error triggering garage door: %s", e)
            exit(1)

    def __del__(self):
        self.relay.off()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)

    try:
        My_Garage = GarageDoor(1)

        while True:
            state = My_Garage.read_state()
            logging.info("Garage door state: %s", state)

            if state == 1:
                My_Garage.trigger()
            elif state == 0:
                My_Garage.trigger()
            else:
                logging.error("Invalid state read from Automation HAT")
                exit(1)

            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Shutting down")
        My_Garage.relay.off()
        exit(0)

