import serial
import minimalmodbus
import time

class Servo:
    def __init__(self, port, baudrate, slave_address):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.ser = serial.Serial(port, baudrate, timeout=1)
        self.mm = minimalmodbus.Instrument(slave_address, self.ser)

    def set_operation_mode(self, mode):
        if mode not in [0, 1, 2, 3]:
            raise ValueError("Invalid operation mode")
        self.mm.write_register(0x3500, mode)

    def write_position_command(self, value):
        if value < 0 or value > 100:
            raise ValueError("Invalid position value")
        self.mm.write_register(0x4000, value)

    def write_velocity_command(self, value):
        if value < 0 or value > 100:
            raise ValueError("Invalid velocity value")
        self.mm.write_register(0x6F00, value)

    def read_position_feedback(self):
        return self.mm.read_registers(0x3700, 2)

    def read_velocity_feedback(self):
        return self.mm.read_registers(0x3B00, 2)

    def start(self):
        self.mm.write_register(0x3100, 0x000F)

    def stop(self):
        self.mm.write_register(0x3100, 0x0006)

    def read_status(self):
        return self.mm.read_register(0x3000)

    def close(self):
        self.ser.close()

if __name__ == '__main__':
    try:
        servo = Servo('/dev/serial0', 115200, 1)
        servo.set_operation_mode(1)
        servo.write_position_command(50)
        servo.write_velocity_command(50)
        servo.start()
        time.sleep(5)
        position = servo.read_position_feedback()
        velocity = servo.read_velocity_feedback()
        print(f"Position: {position}, Velocity: {velocity}")
        servo.stop()
        servo.close()
    except serial.SerialException:
        print("Serial port not available")
    except minimalmodbus.InvalidResponseError:
        print("Invalid response from servo")
    except minimalmodbus.NoResponseError:
        print("No response from servo")
    except ValueError as e:
        print(e)
    except KeyboardInterrupt:
        print("Interrupted by user")
    finally:
        servo.close()

