import smbus2
import datetime

class DS1338:
    def __init__(self, i2c_bus=1, i2c_addr=0x68):
        self.i2c_bus = smbus2.SMBus(i2c_bus)
        self.i2c_addr = i2c_addr
        self.verify_device()

    def verify_device(self):
        try:
            self.i2c_bus.read_byte(self.i2c_addr)
        except OSError:
            raise RuntimeError("DS1338 not found on I2C bus")

    def read_register(self, reg):
        try:
            data = self.i2c_bus.read_byte_data(self.i2c_addr, reg)
        except OSError:
            raise RuntimeError("I2C bus error")
        return data

    def write_register(self, reg, data):
        try:
            self.i2c_bus.write_byte_data(self.i2c_addr, reg, data)
        except OSError:
            raise RuntimeError("I2C bus error")

    def read_seconds(self):
        return self.read_register(0x00)

    def read_minutes(self):
        return self.read_register(0x01)

    def read_hours(self):
        hours = self.read_register(0x02)
        return hours & 0x3f

    def read_date(self):
        return self.read_register(0x04)

    def read_month(self):
        return self.read_register(0x05)

    def read_year(self):
        return self.read_register(0x06)

    def read_datetime(self, century=21):
        seconds = self.read_seconds()
        minutes = self.read_minutes()
        hours = self.read_hours()
        date = self.read_date()
        month = self.read_month()
        year = self.read_year()
