import datetime

class DS1338:
    def __init__(self, bus=1, address=0x68):
        self.bus = smbus2.SMBus(bus)
        self.address = address
        self.open()

    def open(self):
        try:
            self.bus.open(self.address)
        except IOError as e:
            raise IOError(f"Failed to open SMBus: {e}")

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def read_all(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, 0x00, 7)
        except IOError as e:
            raise IOError(f"Failed to read from SMBus: {e}")

        year = data[0] & 0xff
        month = data[1] & 0xff
        date = data[2] & 0xff
        day = data[3] & 0xff
        hours = data[4] & 0xff
        minutes = data[5] & 0xff
        seconds = data[6] & 0xff

        return (year, month, date, day, hours, minutes, seconds)

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime.datetime(year, month, date, hours, minutes, seconds, tzinfo=datetime.timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (0 <= year <= 99):
            raise ValueError("Year must be between 0 and 99")
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        if not (1 <= day <= 7):
            raise ValueError("Day must be between 1 and 7")
        if not (0 <= hours <= 23):
            raise ValueError("Hours must be between 0 and 23")
        if not (0 <= minutes <= 59):
            raise ValueError("Minutes must be between 0 and 59")
        if not (0 <= seconds <= 59):
            raise ValueError("Seconds must be between 0 and 59")

        data = [
            (year & 0xff) | 0x80,
            (month & 0xff) | 0x80,
            (date & 0xff) | 0x80,
            (day & 0xff) | 0x80,
            (hours & 0xff) | 0x80,
            (minutes & 0xff) | 0x80,
            (seconds & 0xff) | 0x80
        ]

        try:
            self.bus.write_i2c_block_data(self.address, 0x00, data)
        except IOError as e:
            raise IOError(f"Failed to write to SMBus: {e}")

    def write_datetime(self, dt):
        self.write_all(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second)

    def write_now(self):
        self.write_datetime(datetime.datetime.now(datetime.timezone.utc))

if __name__ == "__main__":
    try:
        with DS1338() as rtc:
            print(rtc.read_datetime())
    except IOError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

