import smbus2
import RPi.GPIO as GPIO
import paho.mqtt.client as mqtt

logging.basicConfig(level=logging.INFO)

def transmit_rf_code(code, gpio_pin, transmission_repeat):
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(gpio_pin, GPIO.OUT)
    for i in range(transmission_repeat):
        for bit in code:
            if bit == '1':
                GPIO.output(gpio_pin, GPIO.HIGH)
                time.sleep(0.001)
                GPIO.output(gpio_pin, GPIO.LOW)
            else:
                GPIO.output(gpio_pin, GPIO.LOW)
                time.sleep(0.001)
                GPIO.output(gpio_pin, GPIO.HIGH)
        time.sleep(0.01)
    GPIO.cleanup(gpio_pin)

def read_rtc():
    try:
        bus = smbus2.SMBus(1)
        seconds = bus.read_byte_data(0x68, 0x00)
        minutes = bus.read_byte_data(0x68, 0x01)
        hours = bus.read_byte_data(0x68, 0x02)
        return (seconds, minutes, hours)
    except:
        logging.error("Error reading RTC")
        return None

def main():
    try:
        with open("irrigation_config.json") as f:
            config = json.load(f)
    except:
        logging.error("Error loading config file")
        return 1

    try:
        zone = int(sys.argv[1])
        action = sys.argv[2]
    except:
        logging.error("Invalid command-line arguments")
        return 1

    if action == "on":
        code = config["zone{}_on_code".format(zone)]
    elif action == "off":
        code = config["zone{}_off_code".format(zone)]
    else:
        logging.error("Invalid action")
        return 1

    gpio_pin = config.get("gpio_pin", 17)
    transmission_repeat = config.get("transmission_repeat", 3)

    try:
        transmit_rf_code(code, gpio_pin, transmission_repeat)
    except:
        logging.error("Error transmitting RF code")
        return 1

    return 0

if __name__ == "__main__":
    sys.exit(main())

