import serial
import time

class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.ser = None

        try:
            self.ser = serial.Serial(port, baud_rate, timeout=timeout)
        except serial.SerialException as e:
            print(f"Error opening serial port: {e}")
            return

        if not self.test_connection():
            print("Error connecting to ESP8266")
            self.ser.close()
            return

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        try:
            self.ser.write(command.encode())
            response = self.ser.read_until(wait_for, timeout)
            return response
        except serial.SerialException as e:
            print(f"Error sending command: {e}")
            return None

    def test_connection(self):
        response = self._send_command('AT', timeout=1.0, wait_for=b'OK')
        return response == b'OK'

    def restart(self):
        self._send_command('AT+RST', timeout=1.0, wait_for=b'ready')
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        response = self._send_command(f'AT+CWJAP="{ssid}","{password}"', timeout=10.0, wait_for=b'OK')
        return response == b'OK'

    def disconnect_wifi(self):
        self._send_command('AT+CWQAP', timeout=1.0, wait_for=b'OK')
        return True

    def get_ip(self):
        response = self._send_command('AT+CIFSR', timeout=1.0, wait_for=b'OK')
        if response == b'OK':
            return response.decode().split(':')[1].strip()
        else:
            return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if headers is None:
            headers = {}
        if data is None:
            data = b''

        response = self._send_command(f'AT+CIPSTART="TCP","{host}","{port}"', timeout=1.0, wait_for=b'OK')
        if response != b'OK':
            return None

        response = self._send_command(f'AT+CIPSEND={len(data)}', timeout=1.0, wait_for=b'OK')
        if response != b'OK':
            return None

        response = self._send_command(f'{method} {url} HTTP/1.1\r\nHost: {host}\r\n{headers}\r\n\r\n{data}', timeout=1.0, wait_for=b'OK')
        if response != b'OK':
            return None

        response = self._send_command(f'AT+CIPCLOSE', timeout=1.0, wait_for=b'OK')
        if response != b'OK':
            return None

        return response

    def receive_http_response(self, timeout=5.0):
        response = self._send_command(f'AT+CIPRECV', timeout=timeout, wait_for=b'OK')
        if response != b'OK':
            return None

        response = self._send_command(f'AT+CIPCLOSE', timeout=1.0, wait_for=b'OK')
        if response != b'OK':
            return None

        return response

if __name__ == '__main__':
    esp = ESP8266()
    if not esp.test_connection():
        print("Error connecting to ESP8266")
        exit(1)

    if not esp.connect_wifi('my_ssid', 'my_password'):
        print("Error connecting to Wi-Fi")
        exit(1)

    ip = esp.get_ip()
    if ip is None:
        print("Error getting IP address")
        exit(1)

    print(f"IP address: {ip}")

    response = esp.send_http_request('GET', 'http://www.example.com', 'www.example.com')
    if response is None:
        print("Error sending HTTP request")
        exit(1)

    print(f"HTTP response: {response}")

    response = esp.receive_http_response()
    if response is None:
        print("Error receiving HTTP response")
        exit(1)

    print(f"HTTP response: {response}")

    esp.disconnect_wifi()
    esp.ser.close()

