import serial
import time
import logging
from dataclasses import dataclass
from gpiozero import GPIOZero
from picamera2 import PiCamera2
from adafruit_circuitpython_gps import GPS
from paho.mqtt.client import Client

@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    satellite_count: int

class GPSReader:
    def __init__(self, port, baudrate):
        self.port = port
        self.baudrate = baudrate
        self.serial = None
        self.gps = None
        self.client = None

    def connect(self):
        try:
            self.serial = serial.Serial(self.port, self.baudrate)
            self.gps = GPS(self.serial)
            self.client = Client()
            self.client.connect("localhost")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            self.disconnect()
            return False
        except GPSException as e:
            logging.error(f"Failed to initialize GPS: {e}")
            self.disconnect()
            return False
        except MQTTException as e:
            logging.error(f"Failed to connect to MQTT broker: {e}")
            self.disconnect()
            return False
        return True

    def disconnect(self):
        if self.serial is not None:
            self.serial.close()
            self.serial = None
        if self.gps is not None:
            self.gps.close()
            self.gps = None
        if self.client is not None:
            self.client.disconnect()
            self.client = None

    def read_gps(self):
        while True:
            try:
                line = self.serial.readline()
                if not line:
                    continue
                if line.startswith("$GPGGA"):
                    fields = line.split(",")
                    if len(fields) < 15:
                        logging.warning(f"Invalid GPGGA sentence: {line}")
                        continue
