        self.baudrate = baudrate
        self.ser = None
        self.read_timeout = 5
        self.write_timeout = 5
        self.rx_buffer_size = 1024
        self.tx_buffer_size = 1024
        self.max_retries = 3
        self.retry_delay = 1

        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=self.read_timeout)
        except serial.SerialException:
            print("Serial port unavailable or busy")
            raise

    def _send_command(self, command, delay=1, max_retries=3):
        for i in range(max_retries):
            try:
                self.ser.write(command.encode())
                time.sleep(delay)
                response = self.ser.readline().decode().strip()
                if response in ('OK', 'ERROR', 'FAIL'):
                    return response
            except serial.SerialException:
                print("Serial port unavailable or busy")
                raise
        return None

    def _read_response(self):
        try:
            response = self.ser.readline().decode().strip()
            if response in ('OK', 'ERROR', 'FAIL'):
                return response
            else:
                return None
        except serial.SerialException:
            print("Serial port unavailable or busy")
            raise

    def test_connection(self):
        response = self._send_command('AT\r\n')
        if response == 'OK':
            return True
        else:
            return False

    def restart(self):
        response = self._send_command('AT+RST\r\n', delay=2)
        if response == 'OK':
            return True
        else:
            return False

    def connect_wifi(self, ssid, password):
        response = self._send_command('AT+CWJAP_CUR="{}","{}"\r\n'.format(ssid, password), delay=5)
        if 'WIFI GOT IP' in response:
            return True
        else:
            return False

    def __del__(self):
        if self.ser is not None:
            self.ser.close()
