        self.ser.write(b'AT+CGNSPWR=1\r\n')
        time.sleep(1)
        if self.ser.readline().startswith(b'$GPRMC'):
            return True
        else:
            return False

    def detach(self):
        self.ser.write(b'AT+CGNSPWR=0\r\n')
        time.sleep(1)
        if self.ser.readline().startswith(b'$GPRMC'):
            return True
        else:
