import logging
import serial
import time

class SimpleGPS:
    def __init__(self, port="/dev/serial0", baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.ser = None
        self.logger = logging.getLogger(__name__)

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate)
            self.logger.info("Connected to GPS device at %s", self.port)
            return True
        except serial.SerialException as e:
            self.logger.error("Failed to connect to GPS device: %s", e)
            return False
        except OSError as e:
            self.logger.error("Failed to connect to GPS device: %s", e)
            return False

    def read_data(self):
        if self.ser is None:
            return None
        try:
            data = self.ser.readline().decode("utf-8").strip()
            self.logger.debug("Received data: %s", data)
            return data
        except serial.SerialException as e:
            self.logger.error("Failed to read data from GPS device: %s", e)
            return None
        except OSError as e:
            self.logger.error("Failed to read data from GPS device: %s", e)
            return None

    def parse_gga(self, sentence):
        if sentence.startswith("$GPGGA") or sentence.startswith("$GNGGA"):
            try:
                utc_time = sentence[1:6]
                latitude = sentence[7:11]
                longitude = sentence[12:16]
                fix_quality = sentence[17]
                num_satellites = sentence[18]
                return {
                    "utc_time": utc_time,
                    "latitude": float(latitude) / 100,
                    "longitude": float(longitude) / 100,
                    "fix_quality": fix_quality,
                    "num_satellites": num_satellites
                }
            except IndexError as e:
                self.logger.error("Failed to parse GGA sentence: %s", e)
                return None
            except ValueError as e:
                self.logger.error("Failed to parse GGA sentence: %s", e)
                return None
        else:
            return None

    def close(self):
        if self.ser is not None:
            try:
                self.ser.close()
                self.logger.info("Closed GPS connection")
            except serial.SerialException as e:
                self.logger.error("Failed to close GPS connection: %s", e)
            except OSError as e:
                self.logger.error("Failed to close GPS connection: %s", e)
            self.ser = None

if __name__ == "__main__":
    gps = SimpleGPS()
    if gps.connect():
        try:
            while True:
                data = gps.read_data()
                if data is not None:
                    gga = gps.parse_gga(data)
                    if gga is not None:
                        print(gga)
                        time.sleep(1)
        except KeyboardInterrupt:
            gps.close()

