import threading
import time
import json
import serial
import flask

app = flask.Flask(__name__)

class SerialCommunicator:
    def __init__(self, port, baudrate):
        self.port = port
        self.baudrate = baudrate
        self.lock = threading.Lock()
        self.serial = None

    def open(self):
        with self.lock:
            if self.serial is None:
                try:
                    self.serial = serial.Serial(self.port, self.baudrate)
                except serial.SerialException:
                    raise

    def send(self, cmd):
        with self.lock:
            self.serial.write(cmd.encode('ascii'))
            self.serial.flush()

    def receive_line(self):
        with self.lock:
            try:
                return self.serial.readline(timeout=1)
            except serial.SerialException:
                return None

    def close(self):
        with self.lock:
            if self.serial is not None:
                self.serial.close()
                self.serial = None

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

class DataManager:
    def __init__(self):
        self.data = []
        self.lock = threading.Lock()

    def get_all(self):
        with self.lock:
            return self.data

    def get_by_id(self, id):
        with self.lock:
            for item in self.data:
                if item['id'] == id:
                    return item
            return None

    def create(self, name, done):
        with self.lock:
            if not name or not isinstance(done, bool):
                raise ValueError('Invalid input')
            item = {'id': len(self.data) + 1, 'name': name, 'done': done}
            self.data.append(item)
            return item

@app.route('/version', methods=['GET'])
def get_version():
    try:
        serial = SerialCommunicator('/dev/ttyUSB0', 9600)
        serial.send('*IDN?\n')
        response = serial.receive_line()
        if response is None:
            flask.abort(504)
        return flask.Response(response, mimetype='text/plain')
    except serial.SerialException:
        flask.abort(500)
    finally:
        serial.close()

@app.route('/data', methods=['GET'])
def get_data():
    data = DataManager().get_all()
    return flask.jsonify(data)

@app.route('/data/<int:item_id>', methods=['GET'])
def get_item(item_id):
    item = DataManager().get_by_id(item_id)
    if item is None:
        flask.abort(404)
    return flask.jsonify(item)

@app.route('/data', methods=['POST'])
def create_item():
    data = flask.request.get_json()
    if not data or 'name' not in data or 'done' not in data:
        flask.abort(400)
    item = DataManager().create(data['name'], data['done'])
    return flask.jsonify(item)

def signal_handler(signal, frame):
    DataManager().close()
    SerialCommunicator().close()
    flask.request.stop()

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    app.run(host='0.0.0.0', port=5000, debug=False)

