import serial
import json
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

# In-memory data store
data = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False}
]

# Serial port configuration
SERIAL_PORT = "/dev/ttyUSB0"
SERIAL_BAUD = 9600
SERIAL_TIMEOUT = 0.1

# SCPI identification query
SCPI_IDENTIFICATION_QUERY = "*IDN?\n"

# Flask routes
@app.route("/version")
def version():
    try:
        # Open serial port
        ser = serial.Serial(SERIAL_PORT, SERIAL_BAUD, timeout=SERIAL_TIMEOUT)

        # Send SCPI identification query
        ser.write(SCPI_IDENTIFICATION_QUERY.encode())

        # Wait for response
        ser.read(100)

        # Read available bytes
        response = ser.read(100)

        # Close serial port
        ser.close()

        # Return response as text/html with newlines converted to <br>
        return response.decode().replace("\n", "<br>")
    except serial.SerialException:
        abort(503, "Unable to open serial port")
    except serial.SerialTimeoutException:
        abort(503, "Serial port timed out")
    except serial.SerialReadException:
        abort(503, "Unable to read from serial port")

@app.route("/getdata")
def get_data():
    return jsonify(data)

@app.route("/getset/<int:item_id>")
def get_set(item_id):
    try:
        item = next(item for item in data if item["id"] == item_id)
        return jsonify(item)
    except StopIteration:
        abort(404, "Item not found")

@app.route("/getpost/<int:item_id>/<name>")
def get_post(item_id, name):
    try:
        item = next(item for item in data if item["id"] == item_id)
        item["name"] = name
        item["done"] = False
        return jsonify(item)
    except StopIteration:
        abort(404, "Item not found")

@app.route("/postjson", methods=["POST"])
def post_json():
    try:
        # Parse JSON data
        data = request.get_json()

        # Create new item
        item = {"id": len(data) + 1, "name": data.get("name", ""), "done": data.get("done", False)}

        # Append new item to data
        data.append(item)

        # Return updated list as JSON
        return jsonify(data)
    except json.JSONDecodeError:
        abort(400, "Malformed JSON data")

if __name__ == "__main__":
    app.run(host="0.0.0.0")

